import hashlib, re

def canonical(s):
    return ' '.join(s.split())

def shingles(s, n=2):
    w = canonical(s).split()
    return set(tuple(w[i:i+n]) for i in range(len(w)-n+1))

def jaccard(a, b):
    A, B = shingles(a), shingles(b)
    return len(A & B) / len(A | B) if (A | B) else 1.0

