Run the standard-library Python example below. It admits requests in arrival order, models indivisible prefill time and decrements remaining output tokens on each decode iteration. Assert completion and first-token times, then vary the capacity from two to one, insert a very long prefill and compare the resulting tail TTFT. The scheduler reports a trace instead of an average-only metric, permitting verification of each claim.
from dataclasses import dataclass
@dataclass
class Request:
    name: str
    arrival: int
    prefill: int
    decode: int

def schedule(requests, capacity):
    time = 0
    pending = list(requests)
    active = []
    first = {}
    complete = {}
    trace = []
    while pending or active:
        # Admit only requests already arrived; prefill is an indivisible demonstration step.
        while pending and pending[0].arrival <= time and len(active) < capacity:
            r = pending.pop(0)
            active.append([r, r.decode])
            time += r.prefill
            if not r.decode:
                first[r.name] = time
        if active:
            time += 1
            for r, left in active:
                first.setdefault(r.name, time)
            trace.append((time, tuple(r.name for r, left in active)))
            for item in active:
                item[1] -= 1
            finished = [item for item in active if item[1] == 0]
            for r, left in finished:
                complete[r.name] = time
            active = [item for item in active if item[1] > 0]
        elif pending:
            time = max(time, pending[0].arrival)
    return first, complete, trace

r = [Request('A',0,2,4),Request('B',0,1,2),Request('C',3,1,2)]
first, done, trace = schedule(r,2)
assert first == {'A':4,'B':4,'C':7}, first
assert done == {'B':5,'A':8,'C':8}, done
assert len(trace) == 4
print('first',first,'completed',done,'steps',trace)

