import hashlib, json

def digest(operation):
    blob = json.dumps(operation, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(blob.encode()).hexdigest()

class Guard:
    def __init__(self):
        self.done = {}
    def execute(self, op, approval, now):
        if op["tenant"] != approval["tenant"] or now >= approval["expires"]:
            raise PermissionError("scope or expiration")
        if op["action"] != "invite" or digest(op) != approval["operation_hash"]:
            raise PermissionError("unapproved operation")
        request_id = op["request_id"]
        if request_id in self.done:
            old_hash, result = self.done[request_id]
            if old_hash != digest(op):
                raise ValueError("request id reused with changed args")
            return result
        result = f"sent:{op['vendor']}:{op['requisition']}"
        self.done[request_id] = (digest(op), result)
        return result

