def run_plan(steps, execute, verify):
    pending = {s["id"]: s for s in steps}
    if len(pending) != len(steps):
        raise ValueError("duplicate id")
    if any(d not in pending for s in steps for d in s["deps"]):
        raise ValueError("missing dependency")
    passed, trace = set(), []
    while pending:
        ready = [s for s in pending.values() if set(s["deps"]) <= passed]
        if not ready:
            raise ValueError("cycle or blocked dependency")
        step = ready[0]
        observation = execute(step)
        if not verify(step, observation):
            return {"status": "BLOCKED", "trace": trace, "failed": step["id"]}
        trace.append((step["id"], observation))
        passed.add(step["id"])
        del pending[step["id"]]
    return {"status": "SUCCEEDED", "trace": trace}

steps = [dict(id="build", deps=[]), dict(id="deploy", deps=["build"]), dict(id="check", deps=["deploy"])]
