from collections import deque
edges = {
    'cancel_api': [('purchase_order', 'api-contract')],
    'purchase_order': [('invoice_worker', 'sql-read')],
    'invoice_worker': [('invoice_record', 'worker-code')],
    'invoice_record': [('reconciliation', 'job-config')],
    'payroll': []
}
def reach(start, depth_limit):
    found = {start: 0}
    queue = deque([(start, 0)])
    while queue:
        node, depth = queue.popleft()
        if depth >= depth_limit: continue
        for neighbor, source in edges.get(node, []):
            assert source
            if neighbor not in found:
                found[neighbor] = depth + 1
                queue.append((neighbor, depth + 1))
    return found
r = reach('cancel_api', 2)
assert r == {'cancel_api': 0, 'purchase_order': 1, 'invoice_worker': 2}
assert 'payroll' not in r and 'reconciliation' not in r
